using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class GrievanceIntakeTests
{
 class User(int user,int? emp,bool manage=false):ICurrentUser{public string Email=>$"grievance{user}@example.local";public int? EmployeeId=>emp;public int UserId=>user;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>manage?p==Perm.RelationsManage:p is Perm.ScopeCompany or Perm.EmpManage or Perm.TalentManage or Perm.Audit;}
 class Db(DbContextOptions options):AppDbContext(options){public bool Fail;public override async Task<int> SaveChangesAsync(CancellationToken ct=default){var n=await base.SaveChangesAsync(ct);if(Fail)throw new InvalidOperationException("Fictional post-write failure");return n;}}
 static async Task<Db> Open(){var d=new Db(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.EnsureCreatedAsync();d.Add(new Branch{Id=1,Name="Fictional branch"});d.Add(new Department{Id=1,Name="Fictional department"});d.Add(new JobTitle{Id=1,Name="Fictional title"});foreach(var id in new[]{1,2,3}){d.Add(new Employee{Id=id,Code="FIC-"+id,Email=$"employee{id}@example.local",FullName="Fictional employee "+id,DepartmentId=1,BranchId=1,JobTitleId=1,Status=EmployeeStatus.Active});d.Add(new AppUser{Id=id,EmployeeId=id,Email=$"fictional{id}@example.local",IsActive=true,PasswordHash="unused"});}d.Add(new AppUser{Id=4,EmployeeId=1,Email="fictionalalias@example.local",IsActive=true,PasswordHash="unused"});await d.SaveAsync();return d;}
 static GrievanceIntake S(AppDbContext d,User u){var c=new AppClock(TimeProvider.System);return new(d,u,c,new AuditService(d,u,c));}
 static Task Submit(AppDbContext d)=>S(d,new(1,1)).SubmitAsync(" Fictional private title "," PRIVATE-STATEMENT-FICTIONAL ");
 [Fact]public async Task OwnSubmissionAndResponsesArePrivateWithoutCaseAccessOrSideEffects(){await using var d=await Open();await Submit(d);await S(d,new(2,2)).SubmitAsync("Other private title","Other private statement");var own=await S(d,new(1,1)).GetAsync();Assert.Single(own.Submissions);Assert.Empty(own.Responses);Assert.True(own.CanSubmit);int id=own.Submissions.Single().Id;await Assert.ThrowsAsync<DomainException>(()=>S(d,new(2,2)).RespondAsync(id,"No grant"));await S(d,new(3,3,true)).RespondAsync(id,"Fictional employee-visible response");var manager=await S(d,new(3,3,true)).GetAsync();Assert.Equal(2,manager.Submissions.Count);Assert.Single((await S(d,new(1,1)).GetAsync()).Responses);Assert.Empty((await S(d,new(2,2)).GetAsync()).Responses);Assert.Empty(await d.Set<EmployeeCase>().ToListAsync());Assert.Empty(await d.Set<EmployeeCaseAccess>().ToListAsync());Assert.Empty(await d.Set<EmployeeCaseEvent>().ToListAsync());Assert.Empty(await d.Set<Notification>().ToListAsync());Assert.Empty(await d.Set<EmailOutbox>().ToListAsync());Assert.Empty(await d.Set<PayrollLine>().ToListAsync());Assert.All(await d.Set<Employee>().ToListAsync(),e=>Assert.Equal(EmployeeStatus.Active,e.Status));Assert.DoesNotContain(await d.Set<AuditLog>().ToListAsync(),a=>a.Details.Contains("PRIVATE-STATEMENT")||a.Details.Contains("Fictional employee-visible response")||a.Details.Contains("private title"));var view=await S(d,new(1,1)).GetAsync();view.Submissions[0].Statement="Changed detached";view.Responses[0].Note="Changed detached";Assert.Equal("PRIVATE-STATEMENT-FICTIONAL",(await d.Set<EmployeeGrievance>().FindAsync(id))!.Statement);Assert.False(d.ChangeTracker.HasChanges());}
 [Theory][InlineData(1,1)][InlineData(4,1)]public async Task SubmitterAndEmployeeAliasesCannotWriteOwnManagementResponse(int user,int emp){await using var d=await Open();await Submit(d);int id=(await d.Set<EmployeeGrievance>().SingleAsync()).Id;await Assert.ThrowsAsync<DomainException>(()=>S(d,new(user,emp,true)).RespondAsync(id,"Self response"));Assert.Empty(await d.Set<EmployeeGrievanceResponse>().ToListAsync());}
 [Theory][InlineData("inactive")][InlineData("departed")][InlineData("unlinked")][InlineData("mismatch")]public async Task IntakeRequiresCurrentActiveAccountAndWorkingEmployee(string state){await using var d=await Open();var u=(await d.Set<AppUser>().FindAsync(1))!;if(state=="inactive")u.IsActive=false;if(state=="departed")(await d.Set<Employee>().FindAsync(1))!.Status=EmployeeStatus.Terminated;if(state=="unlinked")u.EmployeeId=null;await d.SaveAsync();var service=S(d,new(1,state=="mismatch"?2:1));await Assert.ThrowsAsync<DomainException>(()=>service.SubmitAsync("Title","Statement"));await Assert.ThrowsAsync<DomainException>(()=>service.GetAsync());Assert.Empty(await d.Set<EmployeeGrievance>().ToListAsync());}
 [Fact]public async Task SourcesAndResponsesAreAppendOnlyAndReadDoesNotReturnCaseRecords(){await using var d=await Open();await Submit(d);int id=(await d.Set<EmployeeGrievance>().SingleAsync()).Id;await S(d,new(3,3,true)).RespondAsync(id,"Original response");(await d.Set<EmployeeGrievance>().FindAsync(id))!.Statement="Overwrite";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());d.ChangeTracker.Clear();(await d.Set<EmployeeGrievanceResponse>().SingleAsync()).Note="Overwrite";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());d.ChangeTracker.Clear();d.Remove((await d.Set<EmployeeGrievance>().FindAsync(id))!);await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Theory][InlineData(false)][InlineData(true)]public async Task PostSaveFailureRollsBackDataAndAuditThenCleanRetry(bool response){await using var d=await Open();if(response)await Submit(d);int id=response?(await d.Set<EmployeeGrievance>().SingleAsync()).Id:0;int before=await d.Set<AuditLog>().CountAsync();Task Run()=>response?S(d,new(3,3,true)).RespondAsync(id,"Fictional response"):Submit(d);d.Fail=true;await Assert.ThrowsAsync<InvalidOperationException>(Run);d.Fail=false;Assert.Equal(response?1:0,await d.Set<EmployeeGrievance>().CountAsync());Assert.Empty(await d.Set<EmployeeGrievanceResponse>().ToListAsync());Assert.Equal(before,await d.Set<AuditLog>().CountAsync());Assert.False(d.ChangeTracker.HasChanges());await Run();Assert.Equal(1,await d.Set<EmployeeGrievance>().CountAsync());Assert.Equal(response?1:0,await d.Set<EmployeeGrievanceResponse>().CountAsync());Assert.Equal(before+1,await d.Set<AuditLog>().CountAsync());}
 [Fact]public async Task EmptyAndOversizedContentRejectedAndOuterRollbackLeavesNoIntake(){await using var d=await Open();foreach(var input in new[]{("","Text"),("Title",""),(new string('T',201),"Text"),("Title",new string('S',8001))})await Assert.ThrowsAsync<DomainException>(()=>S(d,new(1,1)).SubmitAsync(input.Item1,input.Item2));await Assert.ThrowsAsync<DomainException>(()=>d.AtomicAsync(async()=>{await Submit(d);throw new DomainException("Fictional outer failure");}));Assert.Empty(await d.Set<EmployeeGrievance>().ToListAsync());Assert.Empty(await d.Set<AuditLog>().ToListAsync());}
 [Fact]public async Task OnLeaveSubmissionAndUnlinkedManagerResponseRespectIndependentRoles(){await using var d=await Open();(await d.Set<Employee>().FindAsync(1))!.Status=EmployeeStatus.OnLeave;d.Add(new AppUser{Id=5,Email="unlinkedmanager@example.local",PasswordHash="unused",IsActive=true});await d.SaveAsync();await Submit(d);var v=await S(d,new(5,null,true)).GetAsync();Assert.False(v.CanSubmit);Assert.Single(v.Submissions);await S(d,new(5,null,true)).RespondAsync(v.Submissions[0].Id,"Unlinked independent response");Assert.Single((await S(d,new(1,1)).GetAsync()).Responses);await Assert.ThrowsAsync<DomainException>(()=>S(d,new(5,null,true)).SubmitAsync("No employee","No submission"));}
 [Fact]public async Task InvalidResponseAndOuterFailureDoNotRetainPartialWrites(){await using var d=await Open();await Submit(d);int id=(await d.Set<EmployeeGrievance>().SingleAsync()).Id;int count=await d.Set<AuditLog>().CountAsync();foreach(var note in new[]{"",new string('N',8001)})await Assert.ThrowsAsync<DomainException>(()=>S(d,new(3,3,true)).RespondAsync(id,note));await Assert.ThrowsAsync<DomainException>(()=>S(d,new(3,3,true)).RespondAsync(999,"Missing intake"));await Assert.ThrowsAsync<DomainException>(()=>d.AtomicAsync(async()=>{await S(d,new(3,3,true)).RespondAsync(id,"Fictional outer rollback");throw new DomainException("Fictional failure");}));Assert.Empty(await d.Set<EmployeeGrievanceResponse>().ToListAsync());Assert.Equal(count,await d.Set<AuditLog>().CountAsync());Assert.False(d.ChangeTracker.HasChanges());}


 static async Task<int> Responded(Db d){await Submit(d);var id=(await d.Set<EmployeeGrievance>().SingleAsync()).Id;await S(d,new(3,3,true)).RespondAsync(id,"ORIGINAL-RESPONSE");return (await d.Set<EmployeeGrievanceResponse>().SingleAsync()).Id;}
 [Fact]public async Task ResponseAppealAndIndependentDispositionPreserveSourcesAndPrivacy(){await using var d=await Open();int response=await Responded(d);await S(d,new(1,1)).AppealAsync(response," PRIVATE-APPEAL ");var a=await d.Set<EmployeeGrievanceAppeal>().SingleAsync();await S(d,new(2,2,true)).DecideAppealAsync(a.Id,"ReconsiderationRecommended"," PRIVATE-DISPOSITION ");var v=await S(d,new(1,1)).GetAsync();Assert.Equal("PRIVATE-APPEAL",Assert.Single(v.Appeals).Note);Assert.Equal("ReconsiderationRecommended",Assert.Single(v.Decisions).Decision);Assert.Empty((await S(d,new(3,3)).GetAsync()).Appeals);Assert.Empty((await S(d,new(3,3)).GetAsync()).Decisions);Assert.Equal("ORIGINAL-RESPONSE",(await d.Set<EmployeeGrievanceResponse>().SingleAsync()).Note);Assert.Empty(await d.Set<EmployeeCase>().ToListAsync());Assert.Empty(await d.Set<Notification>().ToListAsync());Assert.Empty(await d.Set<EmailOutbox>().ToListAsync());Assert.Empty(await d.Set<PayrollLine>().ToListAsync());Assert.All(await d.Set<AuditLog>().ToListAsync(),x=>Assert.False(x.Details.Contains("PRIVATE-APPEAL")||x.Details.Contains("PRIVATE-DISPOSITION")));v.Appeals[0].Note="Detached";v.Decisions[0].Note="Detached";Assert.False(d.ChangeTracker.HasChanges());}
 [Theory][InlineData(2,2)][InlineData(3,3)][InlineData(4,1)]public async Task OnlyOriginalSubmitterCanAppealResponse(int user,int employee){await using var d=await Open();int response=await Responded(d);await Assert.ThrowsAsync<DomainException>(()=>S(d,new(user,employee,true)).AppealAsync(response,"Other actor"));Assert.Empty(await d.Set<EmployeeGrievanceAppeal>().ToListAsync());}
 [Fact]public async Task DuplicateAppealAndDispositionAndSourceOverwriteAreRejected(){await using var d=await Open();int response=await Responded(d);await S(d,new(1,1)).AppealAsync(response,"Original appeal");await Assert.ThrowsAsync<DomainException>(()=>S(d,new(1,1)).AppealAsync(response,"Duplicate"));var a=await d.Set<EmployeeGrievanceAppeal>().SingleAsync();await S(d,new(2,2,true)).DecideAppealAsync(a.Id,"ResponseUpheld","Original disposition");await Assert.ThrowsAsync<DomainException>(()=>S(d,new(2,2,true)).DecideAppealAsync(a.Id,"ResponseUpheld","Duplicate"));(await d.Set<EmployeeGrievanceAppeal>().SingleAsync()).Note="Overwrite";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());d.ChangeTracker.Clear();var decision=await d.Set<EmployeeGrievanceAppealDecision>().SingleAsync();d.Remove(decision);await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Fact]public async Task DispositionExcludesResponderSubjectAliasesAndOrdinaryManager(){await using var d=await Open();int response=await Responded(d);await S(d,new(1,1)).AppealAsync(response,"Appeal");int id=(await d.Set<EmployeeGrievanceAppeal>().SingleAsync()).Id;d.Add(new AppUser{Id=5,EmployeeId=3,Email="responderalias@example.local",IsActive=true,PasswordHash="unused"});await d.SaveAsync();foreach(var actor in new[]{new User(1,1,true),new User(4,1,true),new User(3,3,true),new User(5,3,true),new User(2,2)})await Assert.ThrowsAsync<DomainException>(()=>S(d,actor).DecideAppealAsync(id,"ResponseUpheld","Denied"));Assert.Empty(await d.Set<EmployeeGrievanceAppealDecision>().ToListAsync());}
 [Theory][InlineData(false)][InlineData(true)]public async Task AppealAndDispositionFailureRollBackThenRetryOnce(bool decision){await using var d=await Open();int response=await Responded(d);if(decision)await S(d,new(1,1)).AppealAsync(response,"Appeal");int id=decision?(await d.Set<EmployeeGrievanceAppeal>().SingleAsync()).Id:0;int count=await d.Set<AuditLog>().CountAsync();Task Run()=>decision?S(d,new(2,2,true)).DecideAppealAsync(id,"ResponseUpheld","Disposition"):S(d,new(1,1)).AppealAsync(response,"Appeal");d.Fail=true;await Assert.ThrowsAsync<InvalidOperationException>(Run);d.Fail=false;Assert.Equal(decision?1:0,await d.Set<EmployeeGrievanceAppeal>().CountAsync());Assert.Empty(await d.Set<EmployeeGrievanceAppealDecision>().ToListAsync());Assert.Equal(count,await d.Set<AuditLog>().CountAsync());Assert.False(d.ChangeTracker.HasChanges());await Run();Assert.Equal(count+1,await d.Set<AuditLog>().CountAsync());}
 [Fact]public async Task AppealValidationBindingAndOuterRollbackRetainNoPartialEvidence(){await using var d=await Open();int response=await Responded(d);foreach(var note in new[]{"",new string('X',8001)})await Assert.ThrowsAsync<DomainException>(()=>S(d,new(1,1)).AppealAsync(response,note));await Assert.ThrowsAsync<DomainException>(()=>S(d,new(1,1)).AppealAsync(999,"Missing"));await Assert.ThrowsAsync<DomainException>(()=>d.AtomicAsync(async()=>{await S(d,new(1,1)).AppealAsync(response,"Appeal");throw new DomainException("Outer failure");}));Assert.Empty(await d.Set<EmployeeGrievanceAppeal>().ToListAsync());await S(d,new(1,1)).AppealAsync(response,"Appeal");int id=(await d.Set<EmployeeGrievanceAppeal>().SingleAsync()).Id;await Assert.ThrowsAsync<DomainException>(()=>S(d,new(2,2,true)).DecideAppealAsync(id,"Unknown","Note"));await Assert.ThrowsAsync<DomainException>(()=>S(d,new(2,2,true)).DecideAppealAsync(id,"ResponseUpheld",""));await Assert.ThrowsAsync<DomainException>(()=>d.AtomicAsync(async()=>{await S(d,new(2,2,true)).DecideAppealAsync(id,"ResponseUpheld","Disposition");throw new DomainException("Outer");}));Assert.Empty(await d.Set<EmployeeGrievanceAppealDecision>().ToListAsync());}

 [Theory][InlineData("inactive")][InlineData("departed")][InlineData("unlinked")][InlineData("mismatch")]public async Task AppealRechecksCurrentEmployeeAccountBinding(string state){await using var d=await Open();int response=await Responded(d);var user=(await d.Set<AppUser>().FindAsync(1))!;if(state=="inactive")user.IsActive=false;if(state=="departed")(await d.Set<Employee>().FindAsync(1))!.Status=EmployeeStatus.Terminated;if(state=="unlinked")user.EmployeeId=null;await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d,new(1,state=="mismatch"?2:1)).AppealAsync(response,"Denied"));Assert.Empty(await d.Set<EmployeeGrievanceAppeal>().ToListAsync());}
 [Fact]public async Task AppealDecisionRequiresActiveAccountAndNonemptyBoundedNote(){await using var d=await Open();int response=await Responded(d);await S(d,new(1,1)).AppealAsync(response,"Appeal");int id=(await d.Set<EmployeeGrievanceAppeal>().SingleAsync()).Id;await Assert.ThrowsAsync<DomainException>(()=>S(d,new(2,2,true)).DecideAppealAsync(id,"ResponseUpheld",new string('X',8001)));await Assert.ThrowsAsync<DomainException>(()=>S(d,new(2,2,true)).DecideAppealAsync(999,"ResponseUpheld","Missing"));(await d.Set<AppUser>().FindAsync(2))!.IsActive=false;await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d,new(2,2,true)).DecideAppealAsync(id,"ResponseUpheld","Inactive"));Assert.Empty(await d.Set<EmployeeGrievanceAppealDecision>().ToListAsync());}
}
